def solve(nums1, nums2):
    def merge_and_find_median(a, b):
        m, n = len(a), len(b)
        total = m + n
        if total % 2 == 1:
            return find_kth(a, b, (total + 1) // 2)
        else:
            left = find_kth(a, b, total // 2)
            right = find_kth(a, b, total // 2 + 1)
            return (left + right) / 2.0

    def find_kth(a, b, k):
        if not a:
            return b[k - 1]
        if not b:
            return a[k - 1]
        i = min(len(a) // 2, k - 1)
        j = min(len(b) // 2, k - 1)
        if a[i] > b[j]:
            return find_kth(a, b[j+1:], k - (j + 1))
        else:
            return find_kth(a[i+1:], b, k - (i + 1))

    return merge_and_find_median(nums1, nums2)
