def solve(nums1, nums2):
    def merge(left, right):
        merged = []
        i = j = 0
        while i < len(left) and j < len(right):
            if left[i] < right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                j += 1
        merged.extend(left[i:])
        merged.extend(right[j:])
        return merged

    def find_kth(a, b, k):
        m, n = len(a), len(b)
        if m > n:
            return find_kth(b, a, k)
        left, right = 0, m
        while left <= right:
            partition_a = (left + right) // 2
            partition_b = k - partition_a
            a_left = a[partition_a - 1] if partition_a > 0 else -float('inf')
            a_right = a[partition_a] if partition_a < m else float('inf')
            b_left = b[partition_b - 1] if partition_b > 0 else -float('inf')
            b_right = b[partition_b] if partition_b < n else float('inf')
            if a_left <= b_right and b_left <= a_right:
                return max(a_left, b_left)
            elif a_left > b_right:
                right = partition_a - 1
            else:
                left = partition_a + 1
        return float('inf')

