def solve(nums1, nums2):
    def merge_and_find_median(a, b):
        m, n = len(a), len(b)
        left, right = 0, 0
        total_length = m + n
        median = 0.0

        if total_length % 2 == 1:
            median = find_kth(a, b, total_length // 2 + 1)
        else:
            median = (find_kth(a, b, total_length // 2) + find_kth(a, b, total_length // 2 + 1)) / 2

        return median

    def find_kth(a, b, k):
        if not a:
            return b[k - 1]
        if not b:
            return a[k - 1]

        i = len(a) // 2
        j = len(b) // 2

        if a[i] < b[j]:
            if k > i + 1:
                return find_kth(a[i + 1:], b, k - i - 1)
            else:
                return find_kth(a, b[:j], k)
        else:
            if k > j + 1:
                return find_kth(a, b[j + 1:], k - j - 1)
            else:
                return find_kth(a[:i], b, k)

    return merge_and_find_median(nums1, nums2)
